  if(!$objects||count($objects)>100001)return AssignmentOrderOriginalPdfInspection::invalid();$seen=[];$offset=(int)$last[1];$root=null;
  for($revision=0;$revision<64;$revision++){if(isset($seen[$offset])||$offset<0||$offset>=strlen($b))return AssignmentOrderOriginalPdfInspection::invalid();$seen[$offset]=true;$tail=substr($b,$offset);$prev=null;if(str_starts_with($tail,'xref')){if(!preg_match('/^xref\s+(.*?)(?:trailer\s*<<(.*?)>>)/s',$tail,$x))return AssignmentOrderOriginalPdfInspection::invalid();if(preg_match_all('/(\d{10})\s+(\d{5})\s+n\b/',$x[1],$entries))foreach($entries[1]as$p){$p=(int)$p;if($p>=strlen($b)||!preg_match('/^\d+\s+\d+\s+obj\b/',substr($b,$p)))return AssignmentOrderOriginalPdfInspection::invalid();}$dict=$x[2];}else{if(!preg_match('/^(\d+)\s+(\d+)\s+obj\s*<<(.*?)>>\s*stream\r?\n/s',$tail,$x)||!preg_match('/\/Type\s*\/XRef\b/',$x[3]))return AssignmentOrderOriginalPdfInspection::invalid();$dict=$x[3];if(preg_match('/\/Filter\s*\/(?!FlateDecode\b)/',$dict))return AssignmentOrderOriginalPdfInspection::invalid();if(preg_match('/\/Size\s+(\d+)/',$dict,$z)&&(int)$z[1]>100001)return AssignmentOrderOriginalPdfInspection::invalid();}if($root===null&&preg_match('/\/Root\s+(\d+)\s+(\d+)\s+R/',$dict,$r))$root=$r[1].' '.$r[2];if(preg_match('/\/Encrypt\b/',$dict))return AssignmentOrderOriginalPdfInspection::unsafe();if(preg_match('/\/Prev\s+(\d+)/',$dict,$p))$prev=(int)$p[1];if($prev===null)break;$offset=$prev;if($revision===63)return AssignmentOrderOriginalPdfInspection::invalid();}
